	var in lsInput
	if len(input) > 0 {
		if err := json.Unmarshal(input, &in); err != nil {
			return "", err
		}
	}

	target, err := resolvePathWithinRoot(t.Root, in.Path)
	if err != nil {
		return "", err
	}

	entries, err := os.ReadDir(target)
	if err != nil {
		return "", err
	}

	names := make([]string, 0, len(entries))
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() {
			name += "/"
		}
		names = append(names, name)
	}
	sort.Strings(names)
	return strings.Join(names, "\n"), nil
}

package file

import (
	"fmt"
	"path/filepath"
	"strings"
)

func resolvePathWithinRoot(root, target string) (string, error) {
	if strings.TrimSpace(root) == "" {
		return "", fmt.Errorf("tool root is empty")
	}

	absRoot, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}

	resolvedTarget := absRoot
	if strings.TrimSpace(target) != "" {
		resolvedTarget = filepath.Join(absRoot, target)
	}

	absTarget, err := filepath.Abs(resolvedTarget)
	if err != nil {
		return "", err
	}

	rel, err := filepath.Rel(absRoot, absTarget)
	if err != nil {
		return "", err
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("path escapes workspace root: %s", target)
	}

	// TODO: 如果后续要把文件访问做成严格沙箱，这里还需要补 symlink-aware 校验。
	return absTarget, nil
}

func relativePath(root, target string) string {
	rel, err := filepath.Rel(root, target)
	if err != nil {
		return target
	}
	return filepath.ToSlash(rel)
}

package exec

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	osexec "os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

const (
	defaultTimeoutSeconds = 30
	maxOutputBytes        = 32 * 1024
)

// blockedPatterns 列出禁止执行的 shell 命令模式。
// 策略：阻止破坏性的文件删除和格式化操作，同时保留正常的开发工作流。
// 注意：这是一层防御纵深，主要防止模型意外生成危险命令；
// 真正的隔离边界是 resolveWorkingDir 的工作区路径沙箱。
var blockedPatterns = []*regexp.Regexp{
	// 递归删除（rm -rf / rm -r）
	regexp.MustCompile(`(?i)\brm\b[^;|&]*-[^\s]*r`),
	// 危险的磁盘操作
	regexp.MustCompile(`\b(mkfs|dd\b.*\bof=/dev|fdisk|parted|shred)\b`),
	// fork bomb
	regexp.MustCompile(`:\s*\(\s*\)\s*\{.*:\|:.*\}`),
}

// BashTool 在工作区内运行 shell 命令。
// 安全策略：
//  1. 正则预检，拦截高风险破坏性命令（rm -rf、mkfs 等）；
//  2. 工作目录沙箱：cwd 不允许逃出 Root；
//  3. 强制超时，超时后 kill 整个进程组。
type BashTool struct {
	Root string
}

type bashInput struct {
	Command        string `json:"command"`
	CWD            string `json:"cwd,omitempty"`
	TimeoutSeconds int    `json:"timeout_seconds,omitempty"`
}

func (t *BashTool) Name() string {
	return "Bash"
}

func (t *BashTool) Description() string {
	return "在工作区内安全执行一条 shell 命令。" +
		"破坏性命令（如 rm -rf、mkfs）会被拦截。" +
		"示例输入: {\"command\":\"go test ./...\",\"cwd\":\".\",\"timeout_seconds\":30}"
}

func (t *BashTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"command":{"type":"string"},"cwd":{"type":"string"},"timeout_seconds":{"type":"integer","minimum":1}},"required":["command"]}`)
}

func (t *BashTool) Run(ctx context.Context, input json.RawMessage) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", err
	}

	in, err := decodeBashInput(input)
	if err != nil {
		return "", err
	}

	// 安全预检：拦截高风险命令
	if blocked, pattern := checkCommandSafety(in.Command); blocked {
		return "", fmt.Errorf("命令包含不允许的操作（匹配到危险模式: %s），执行已拦截", pattern)
	}

	workdir, err := resolveWorkingDir(t.Root, in.CWD)
	if err != nil {
		return "", err
	}

	timeout := resolveTimeout(in.TimeoutSeconds)
	execCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	cmd := osexec.CommandContext(execCtx, "bash", "-c", in.Command)
	cmd.Dir = workdir

	var output limitedBuffer
	cmd.Stdout = &output
	cmd.Stderr = &output

	err = cmd.Run()
	renderedOutput := output.String()

	// 超时是框架级错误，直接返回 error，让调用方决策。
	if execCtx.Err() == context.DeadlineExceeded {
		if renderedOutput == "" {
			return "", fmt.Errorf("command timed out after %s", timeout)
		}
		return "", fmt.Errorf("command timed out after %s\noutput:\n%s", timeout, renderedOutput)
	}

	// 命令本身非零退出时，把退出码附在输出末尾作为有价值的信息返回给模型，
	// 而不是作为 Go error——模型需要看到 stderr/stdout 才能判断下一步。
	if err != nil {
		exitInfo := fmt.Sprintf("\n[exit status: %s]", err.Error())
		if renderedOutput == "" {
			return exitInfo, nil
		}
		return renderedOutput + exitInfo, nil
	}

	return renderedOutput, nil
}

// checkCommandSafety 检查命令是否命中危险模式。
// 返回 (true, patternDesc) 表示命中。
func checkCommandSafety(command string) (bool, string) {
	for _, re := range blockedPatterns {
		if re.MatchString(command) {
			return true, re.String()
		}
	}
	return false, ""
}

func decodeBashInput(input json.RawMessage) (bashInput, error) {
	var in bashInput
	if err := json.Unmarshal(input, &in); err != nil {
		return bashInput{}, err
	}
	if strings.TrimSpace(in.Command) == "" {
		return bashInput{}, fmt.Errorf("command is required")
	}
	return in, nil
}

func resolveTimeout(timeoutSeconds int) time.Duration {
	if timeoutSeconds <= 0 {
		return defaultTimeoutSeconds * time.Second
	}
	return time.Duration(timeoutSeconds) * time.Second
}

func resolveWorkingDir(root, cwd string) (string, error) {
	if strings.TrimSpace(root) == "" {
		return "", fmt.Errorf("bash tool root is empty")
	}

	absRoot, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}

	target := absRoot
	if strings.TrimSpace(cwd) != "" {
		target = filepath.Join(absRoot, cwd)
	}

	absTarget, err := filepath.Abs(target)
	if err != nil {
		return "", err
	}

	rel, err := filepath.Rel(absRoot, absTarget)
	if err != nil {
		return "", err
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("cwd escapes workspace root: %s", cwd)
	}

	// TODO: 如果后续安全边界要更严格，这里还要补 symlink-aware 校验，防止软链接逃逸。
	return absTarget, nil
}

type limitedBuffer struct {
	buf       bytes.Buffer
	truncated bool
}

func (b *limitedBuffer) Write(p []byte) (int, error) {
	remaining := maxOutputBytes - b.buf.Len()
	if remaining <= 0 {
		b.truncated = true
		return len(p), nil
	}

	if len(p) > remaining {
		b.truncated = true
		p = p[:remaining]
	}
	_, err := b.buf.Write(p)
	return len(p), err
}

func (b *limitedBuffer) String() string {
	out := b.buf.String()
	if !b.truncated {
		return out
	}
	if out != "" && !strings.HasSuffix(out, "\n") {
		out += "\n"
	}
	return out + "[output truncated]"
}

package webfetch

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
)

const (
	defaultTimeoutSeconds = 30
	maxResponseBytes      = 32 * 1024
)

type Tool struct {
	Client *http.Client
}

type input struct {
	URL            string `json:"url"`
	TimeoutSeconds int    `json:"timeout_seconds,omitempty"`
}

func (t *Tool) Name() string {
	return "WebFetch"
}

func (t *Tool) Description() string {
	return "通过 HTTP(S) 抓取网页内容，并返回状态、内容类型和响应体文本"
}

func (t *Tool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"url":{"type":"string"},"timeout_seconds":{"type":"integer","minimum":1}},"required":["url"]}`)
}

func (t *Tool) Run(ctx context.Context, raw json.RawMessage) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", err
	}

	var in input
	if err := json.Unmarshal(raw, &in); err != nil {
		return "", err
	}
	if strings.TrimSpace(in.URL) == "" {
		return "", fmt.Errorf("url is required")
	}

	parsedURL, err := url.Parse(in.URL)
	if err != nil {
		return "", err
	}
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return "", fmt.Errorf("unsupported URL scheme: %s", parsedURL.Scheme)
	}

	timeout := time.Duration(in.TimeoutSeconds) * time.Second
	if timeout <= 0 {
		timeout = defaultTimeoutSeconds * time.Second
	}
	requestCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	req, err := http.NewRequestWithContext(requestCtx, http.MethodGet, parsedURL.String(), nil)
	if err != nil {
		return "", err
	}

	client := t.Client
	if client == nil {
		client = &http.Client{Timeout: timeout}
	}

	resp, err := client.Do(req)
	if err != nil {
		return "", err
	}
	defer func() { _ = resp.Body.Close() }()

	var body limitedBuffer
	if _, err := io.Copy(&body, resp.Body); err != nil {
		return "", err
	}

	var out strings.Builder
	out.WriteString("status: ")
	out.WriteString(resp.Status)
	out.WriteByte('\n')
	out.WriteString("content-type: ")
	out.WriteString(resp.Header.Get("Content-Type"))
	out.WriteByte('\n')
	out.WriteString("body:\n")
	out.WriteString(body.String())
	return out.String(), nil
}

type limitedBuffer struct {
	buf       bytes.Buffer
	truncated bool
}

func (b *limitedBuffer) Write(p []byte) (int, error) {
	remaining := maxResponseBytes - b.buf.Len()
	if remaining <= 0 {
		b.truncated = true
		return len(p), nil
	}
	if len(p) > remaining {
		b.truncated = true
		p = p[:remaining]
	}
	_, err := b.buf.Write(p)
	return len(p), err
}

func (b *limitedBuffer) String() string {
	out := b.buf.String()
	if !b.truncated {
		return out
	}
	if out != "" && !strings.HasSuffix(out, "\n") {
		out += "\n"
	}
	return out + "[response truncated]"
}

package subagent

import (
	"context"
	"encoding/json"
	"fmt"
	"gocode/internal/loop"
	"gocode/internal/session"
	"gocode/internal/settings"
	"gocode/internal/tool"
	toolexec "gocode/internal/tool/exec"
	toolfile "gocode/internal/tool/file"
	toolwebfetch "gocode/internal/tool/webfetch"
	"gocode/internal/ui"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"
)

type SettingsProvider interface {
	CurrentSettings() settings.Config
}

type Notifier interface {
	OnSystemMessage(event ui.SystemEvent) error
}

type Store interface {
	session.Store
	TranscriptPath(sessionID string) string
}

type Config struct {
	Model    loop.ModelStreamer
	Store    Store
	Root     string
	Settings SettingsProvider
	Notifier Notifier
}

type Manager struct {
	model    loop.ModelStreamer
	store    Store
	root     string
	settings SettingsProvider
	notifier Notifier

	mu    sync.RWMutex
	tasks map[string]TaskSnapshot
}

type Request struct {
	ParentSessionID string
	Prompt          string
	Description     string
	ContextMode     settings.ContextMode
	RunMode         settings.RunMode
}

type Result struct {
	AgentID        string               `json:"agent_id"`
	SessionID      string               `json:"session_id"`
	ContextMode    settings.ContextMode `json:"context_mode"`
	RunMode        settings.RunMode     `json:"run_mode"`
	TranscriptPath string               `json:"transcript_path"`
	Content        string               `json:"content,omitempty"`
}

type TaskStatus string

const (
	TaskRunning   TaskStatus = "running"
	TaskCompleted TaskStatus = "completed"
	TaskFailed    TaskStatus = "failed"
)

type TaskSnapshot struct {
	ID             string               `json:"id"`
	SessionID      string               `json:"session_id"`
	Description    string               `json:"description,omitempty"`
	Prompt         string               `json:"prompt"`
	ContextMode    settings.ContextMode `json:"context_mode"`
	RunMode        settings.RunMode     `json:"run_mode"`
	Status         TaskStatus           `json:"status"`
	TranscriptPath string               `json:"transcript_path"`
	StartedAt      time.Time            `json:"started_at"`
	FinishedAt     *time.Time           `json:"finished_at,omitempty"`
	Content        string               `json:"content,omitempty"`
	Error          string               `json:"error,omitempty"`
}

type sinkUI struct{}

var _ ui.UI = sinkUI{}

func NewManager(cfg Config) *Manager {
	return &Manager{
		model:    cfg.Model,
		store:    cfg.Store,
		root:     cfg.Root,
		settings: cfg.Settings,
		notifier: cfg.Notifier,
		tasks:    make(map[string]TaskSnapshot),
	}
}

func (m *Manager) Run(ctx context.Context, req Request) (Result, error) {
	req = m.normalizeRequest(req)
	if err := validateRequest(req); err != nil {
		return Result{}, err
	}
	if err := m.validate(); err != nil {
		return Result{}, err
	}

	sessionID, err := m.prepareSession(ctx, req)
	if err != nil {
		return Result{}, err
	}
	content, err := m.runSession(ctx, sessionID, req.Prompt)
	result := Result{
		AgentID:        sessionID,
		SessionID:      sessionID,
		ContextMode:    req.ContextMode,
		RunMode:        settings.RunModeSync,
		TranscriptPath: m.store.TranscriptPath(sessionID),
		Content:        content,
	}
	if err != nil {
		return result, err
	}
	return result, nil
}

func (m *Manager) Launch(ctx context.Context, req Request) (TaskSnapshot, error) {
	req = m.normalizeRequest(req)
	req.RunMode = settings.RunModeBackground
	if err := validateRequest(req); err != nil {
		return TaskSnapshot{}, err
	}
	if err := m.validate(); err != nil {
		return TaskSnapshot{}, err
	}

	sessionID, err := m.prepareSession(ctx, req)
	if err != nil {
		return TaskSnapshot{}, err
	}

	task := TaskSnapshot{
		ID:             sessionID,
		SessionID:      sessionID,
		Description:    req.Description,
		Prompt:         req.Prompt,
		ContextMode:    req.ContextMode,
		RunMode:        settings.RunModeBackground,
		Status:         TaskRunning,
		TranscriptPath: m.store.TranscriptPath(sessionID),
		StartedAt:      time.Now().UTC(),
	}
	m.setTask(task)

	go m.runBackground(sessionID, req)
	return task, nil
}

func (m *Manager) Status(id string) (TaskSnapshot, bool) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	task, ok := m.tasks[strings.TrimSpace(id)]
	return task, ok
}

func (m *Manager) ListTasks() []TaskSnapshot {
	m.mu.RLock()
	defer m.mu.RUnlock()
	tasks := make([]TaskSnapshot, 0, len(m.tasks))
	for _, task := range m.tasks {
		tasks = append(tasks, task)
	}
	sort.Slice(tasks, func(i, j int) bool {
		return tasks[i].StartedAt.Before(tasks[j].StartedAt)
	})
	return tasks
}

func (m *Manager) normalizeRequest(req Request) Request {
	cfg := settings.DefaultConfig()
	if m != nil && m.settings != nil {
		cfg = m.settings.CurrentSettings()
	}
	if req.ContextMode == "" {
		req.ContextMode = cfg.Subagent.DefaultContextMode
	}
	if req.RunMode == "" {
		req.RunMode = cfg.Subagent.DefaultRunMode
	}
	req.ContextMode = settings.NormalizeContextMode(req.ContextMode)
	req.RunMode = settings.NormalizeRunMode(req.RunMode)
	req.Prompt = strings.TrimSpace(req.Prompt)
	req.Description = strings.TrimSpace(req.Description)
	return req
}

func validateRequest(req Request) error {
	if strings.TrimSpace(req.Prompt) == "" {
		return fmt.Errorf("prompt is required")
	}
	if req.ContextMode == settings.ContextModeFork && strings.TrimSpace(req.ParentSessionID) == "" {
		return fmt.Errorf("parent_session_id is required for fork context")
	}
	return nil
}

func (m *Manager) validate() error {
	if m == nil {
		return fmt.Errorf("subagent manager is nil")
	}
	if m.model == nil {
		return fmt.Errorf("subagent model is nil")
	}
	if m.store == nil {
		return fmt.Errorf("subagent store is nil")
	}
	if strings.TrimSpace(m.root) == "" {
		return fmt.Errorf("subagent root is empty")
	}
	return nil
}

func (m *Manager) prepareSession(ctx context.Context, req Request) (string, error) {
	sessionID, err := session.GenerateSessionID()
	if err != nil {
		return "", err
	}
	switch req.ContextMode {
	case settings.ContextModeFork:
		if _, err := m.store.Fork(ctx, session.ForkRequest{
			SessionID:        sessionID,
			ParentSessionID: strings.TrimSpace(req.ParentSessionID),
			ForkFromSeq:     -1,
		}); err != nil {
			return "", err
		}
	default:
		if _, err := m.store.CreateRoot(ctx, session.CreateRootRequest{SessionID: sessionID}); err != nil {
			return "", err
		}
	}
	return sessionID, nil
}

func (m *Manager) runSession(ctx context.Context, sessionID, prompt string) (string, error) {
	runner := loop.NewRunnerWithInstructionRoot(m.model, sinkUI{}, newBaseToolRegistry(m.root), m.store, sessionID, m.root)
	msg, err := runner.RunTurn(ctx, prompt)
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(msg.Content), nil
}

func (m *Manager) runBackground(sessionID string, req Request) {
	ctx := context.Background()
	content, err := m.runSession(ctx, sessionID, req.Prompt)
	now := time.Now().UTC()

	m.mu.Lock()
	task := m.tasks[sessionID]
	task.FinishedAt = &now
	if err != nil {
		task.Status = TaskFailed
		task.Error = err.Error()
	} else {
		task.Status = TaskCompleted
		task.Content = content
	}
	m.tasks[sessionID] = task
	m.mu.Unlock()

	m.notifyTaskFinished(task)
}

func (m *Manager) setTask(task TaskSnapshot) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.tasks[task.ID] = task
}

func (m *Manager) notifyTaskFinished(task TaskSnapshot) {
	if m == nil || m.notifier == nil {
		return
	}
	status := string(task.Status)
	body := fmt.Sprintf("%s finished with status=%s", shortID(task.ID), status)
	if task.Error != "" {
		body += ": " + task.Error
	} else if task.Content != "" {
		body += ": " + summarize(task.Content)
	}
	_ = m.notifier.OnSystemMessage(ui.SystemEvent{
		Title: "subagent",
		Body:  body,
	})
}

func newBaseToolRegistry(root string) *tool.Registry {
	registry := tool.NewRegistry()
	registry.Register(&toolfile.LSTool{Root: root})
	registry.Register(&toolfile.ReadTool{Root: root})
	registry.Register(&toolfile.WriteTool{Root: root})
	registry.Register(&toolfile.GrepTool{Root: root})
	registry.Register(&toolfile.GlobTool{Root: root})
	registry.Register(&toolexec.BashTool{Root: root})
	registry.Register(&toolwebfetch.Tool{})
	return registry
}

func shortID(id string) string {
	if len(id) <= 8 {
		return id
	}
	return id[:8]
}

func summarize(text string) string {
	fields := strings.Join(strings.Fields(text), " ")
	runes := []rune(fields)
	if len(runes) <= 160 {
		return fields
	}
	return string(runes[:160]) + "..."
}

func (sinkUI) OnAssistantDelta(string) error {
	return nil
}

func (sinkUI) OnToolCall(ui.ToolCallEvent) error {
	return nil
}

func (sinkUI) OnToolResult(ui.ToolResultEvent) error {
	return nil
}

func (sinkUI) OnDone() error {
	return nil
}

type subagentTool struct {
	manager         *Manager
	parentSessionID string
}

type statusTool struct {
	manager *Manager
}

type toolInput struct {
	Prompt      string               `json:"prompt"`
	Description string               `json:"description,omitempty"`
	ContextMode settings.ContextMode `json:"context_mode,omitempty"`
	RunMode     settings.RunMode     `json:"run_mode,omitempty"`
}

type statusInput struct {
	ID string `json:"id,omitempty"`
}

func NewTool(manager *Manager, parentSessionID string) tool.Tool {
	return &subagentTool{manager: manager, parentSessionID: parentSessionID}
}

func NewStatusTool(manager *Manager) tool.Tool {
	return &statusTool{manager: manager}
}

func (t *subagentTool) Name() string {
	return "Subagent"
}

func (t *subagentTool) Description() string {
	return "Launch a focused subagent. Use context_mode empty for a self-contained spec, or fork to inherit committed parent session history. run_mode sync waits for the result; background returns a task id."
}

func (t *subagentTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"prompt":{"type":"string"},"description":{"type":"string"},"context_mode":{"type":"string","enum":["empty","fork"]},"run_mode":{"type":"string","enum":["sync","background"]}},"required":["prompt"]}`)
}

func (t *subagentTool) Run(ctx context.Context, raw json.RawMessage) (string, error) {
	var in toolInput
	if err := json.Unmarshal(raw, &in); err != nil {
		return "", err
	}
	req := Request{
		ParentSessionID: t.parentSessionID,
		Prompt:          in.Prompt,
		Description:     in.Description,
		ContextMode:     in.ContextMode,
		RunMode:         in.RunMode,
	}
	req = t.manager.normalizeRequest(req)
	if req.RunMode == settings.RunModeBackground {
		task, err := t.manager.Launch(ctx, req)
		if err != nil {
			return "", err
		}
		return marshalResult(task), nil
	}
	result, err := t.manager.Run(ctx, req)
	if err != nil {
		return "", err
	}
	return marshalResult(result), nil
}

func (t *statusTool) Name() string {
	return "SubagentStatus"
}

func (t *statusTool) Description() string {
	return "List background subagent tasks or get one task by id."
}

func (t *statusTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"id":{"type":"string"}}}`)
}

func (t *statusTool) Run(ctx context.Context, raw json.RawMessage) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", err
	}
	var in statusInput
	if len(raw) > 0 {
		if err := json.Unmarshal(raw, &in); err != nil {
			return "", err
		}
	}
	if strings.TrimSpace(in.ID) != "" {
		task, ok := t.manager.Status(in.ID)
		if !ok {
			return "", fmt.Errorf("subagent task not found: %s", in.ID)
		}
		return marshalResult(task), nil
	}
	return marshalResult(t.manager.ListTasks()), nil
}

func marshalResult(v any) string {
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return fmt.Sprintf("%v", v)
	}
	return string(data)
}

func TranscriptPath(root, sessionID string) string {
	return filepath.Join(root, ".ccagent", "sessions", sessionID, "transcript.jsonl")
}

package loop

import (
	"context"
	"encoding/json"
	"fmt"
	"gocode/internal/message"
	"gocode/internal/model"
	"gocode/internal/tool"
	"gocode/internal/ui"
	"html"
	"strings"
	"sync"
)

const (
	maxToolRounds       = 20
	toolUseResponseType = "tool_use"
)

// ModelStreamer 是 loop 层依赖的最小模型流式接口。
type ModelStreamer interface {
	StreamMessage(ctx context.Context, messages []message.Message) (<-chan model.StreamEvent, error)
}

// HistoryStore 是 Runner 依赖的最小历史存储接口。
// loop 层只关心“加载历史”和“追加历史”，不需要知道完整 session 能力。
type HistoryStore interface {
	LoadResolvedHistory(ctx context.Context, sessionID string) ([]message.Message, error)
	Append(ctx context.Context, sessionID string, msgs ...message.Message) error
}

// Runner 负责单轮工具闭环调度。
type Runner struct {
	mu        sync.RWMutex
	model     ModelStreamer
	ui        ui.UI
	registry  *tool.Registry
	store     HistoryStore
	sessionID string
	prompt    *PromptBuilder
	// history 保存“已经成功完成”的多轮对话消息。
	// 当前调用路径是串行的，因此这里先不引入锁。
	// TODO: 如果后续要把 Runner 暴露给并发调用方，需要为 history 增加互斥保护。
	history    []message.Message
	usage      model.Usage
	usageKnown bool
}

type ContextStats struct {
	UsedTokens  int
	CacheTokens int
	LimitTokens int
}

type outputMode int

const (
	outputModeUndecided outputMode = iota
	outputModeVisible
	outputModeSuppressed
)

type turnState struct {
	content     strings.Builder
	pending     strings.Builder
	wroteOutput bool
	outputMode  outputMode
}

type toolUseEnvelope struct {
	Type  string          `json:"type"`
	ID    string          `json:"id"`
	Name  string          `json:"name"`
	Input json.RawMessage `json:"input"`
}

// NewRunner 创建调度器。
func NewRunner(model ModelStreamer, output ui.UI, registry *tool.Registry, store HistoryStore, sessionID string) *Runner {
	return NewRunnerWithInstructionRoot(model, output, registry, store, sessionID, "")
}

// NewRunnerWithInstructionRoot 创建带项目指令根目录的调度器。
func NewRunnerWithInstructionRoot(model ModelStreamer, output ui.UI, registry *tool.Registry, store HistoryStore, sessionID, instructionRoot string) *Runner {
	return &Runner{
		model:     model,
		ui:        output,
		registry:  registry,
		store:     store,
		sessionID: sessionID,
		prompt:    NewPromptBuilder(NewInstructionManager(instructionRoot)),
	}
}

// RunTurn 执行一次最小工具闭环流程，并返回最终 assistant 消息。
func (runner *Runner) RunTurn(ctx context.Context, input string) (message.Message, error) {
	if err := runner.validate(); err != nil {
		return message.Message{}, err
	}
	runner.clearTurnUsage()
	defer runner.clearTurnUsage()

	if runner.historyIsNil() && runner.store != nil {
		messages, err := runner.store.LoadResolvedHistory(ctx, runner.sessionID)
		if err != nil {
			return message.Message{}, err
		}
		runner.setHistoryIfNil(messages)
	}

	// 每一轮都基于“已提交的历史副本”工作。
	// 这样即使当前轮中途失败，也不会污染下一轮上下文。
	history := runner.buildTurnHistory(input)
	for round := 0; round < maxToolRounds; round++ {
		assistantMessage, err := runner.runModelTurn(ctx, history)
		if err != nil {
			return message.Message{}, err
		}
		history = append(history, assistantMessage)

		if assistantMessage.ToolUse == nil {
			// 只有当本轮完整结束时，才把本轮消息提交为新的会话历史。
			if err := runner.commitHistory(ctx, history); err != nil {
				return message.Message{}, err
			}
			return assistantMessage, nil
		}

		toolResult, err := runner.runToolCall(ctx, assistantMessage.ToolUse)
		if err != nil {
			return message.Message{}, err
		}
		history = append(history, toolResult)
	}

	return message.Message{}, fmt.Errorf("tool loop exceeded max rounds: %d", maxToolRounds)
}

func (runner *Runner) validate() error {
	if runner == nil || runner.model == nil || runner.ui == nil {
		return fmt.Errorf("runner 未初始化: model 或 ui 为空")
	}
	return nil
}

func (runner *Runner) runModelTurn(ctx context.Context, history []message.Message) (message.Message, error) {
	events, err := runner.model.StreamMessage(ctx, runner.buildModelMessages(history))
	if err != nil {
		return message.Message{}, err
	}

	return runner.consumeStream(ctx, events)
}

func buildUserMessages(input string) []message.Message {
	return []message.Message{
		{
			Role:    message.RoleUser,
			Content: input,
		},
	}
}

// buildTurnHistory 复制已完成历史，并在尾部追加当前用户输入。
// 这样单轮执行可以安全地在本地 history 上反复追加 tool_use / tool_result。
func (runner *Runner) buildTurnHistory(input string) []message.Message {
	runner.mu.RLock()
	history := append([]message.Message(nil), runner.history...)
	runner.mu.RUnlock()
	history = append(history, buildUserMessages(input)...)
	return history
}

// commitHistory 在一次 turn 成功结束后提交历史。
// 先计算新增消息，再更新内存、持久化磁盘，两步顺序不能颠倒。
func (runner *Runner) commitHistory(ctx context.Context, history []message.Message) error {
	if runner.store != nil {
		// 在更新 runner.history 之前，先用旧长度算出本轮新增的消息。
		// runner.history 是上一轮结束时的状态，history 是本轮完整状态。
		runner.mu.RLock()
		prevLen := len(runner.history)
		runner.mu.RUnlock()
		newMsgs := history[prevLen:]
		if len(newMsgs) > 0 {
			if err := runner.store.Append(ctx, runner.sessionID, newMsgs...); err != nil {
				return fmt.Errorf("保存会话历史失败: %w", err)
			}
		}
	}

	// 持久化成功后再更新内存副本。
	runner.mu.Lock()
	runner.history = append([]message.Message(nil), history...)
	runner.mu.Unlock()
	return nil
}

// ResetHistory 清空当前对话上下文。
// 交互式 REPL 可以用它实现 /clear 这类命令。
// TODO: 接入会话持久化后，这里还需要同步清理对应的 session 数据。
func (runner *Runner) ResetHistory() {
	runner.mu.Lock()
	defer runner.mu.Unlock()
	runner.history = []message.Message{}
}

func (runner *Runner) ContextStats(limitTokens int, draft string) ContextStats {
	if limitTokens <= 0 {
		limitTokens = 1024 * 1024
	}
	if runner == nil {
		return ContextStats{LimitTokens: limitTokens}
	}

	runner.mu.RLock()
	history := append([]message.Message(nil), runner.history...)
	usage := runner.usage
	usageKnown := runner.usageKnown
	runner.mu.RUnlock()

	if strings.TrimSpace(draft) != "" {
		history = append(history, buildUserMessages(draft)...)
	}
	messages := runner.buildModelMessages(history)
	used := estimateMessagesTokens(messages)
	cache := 0
	if usageKnown {
		cache = usage.CacheReadInputTokens
		if cache < 0 {
			cache = 0
		}
		if cache > used {
			cache = used
		}
	}
	return ContextStats{
		UsedTokens:  used,
		CacheTokens: cache,
		LimitTokens: limitTokens,
	}
}

func (runner *Runner) historyIsNil() bool {
	runner.mu.RLock()
	defer runner.mu.RUnlock()
	return runner.history == nil
}

func (runner *Runner) setHistoryIfNil(history []message.Message) {
	runner.mu.Lock()
	defer runner.mu.Unlock()
	if runner.history == nil {
		runner.history = append([]message.Message(nil), history...)
	}
}

func buildSystemMessage(content string) message.Message {
	return message.Message{
		Role:    message.RoleSystem,
		Content: content,
	}
}

func buildAssistantMessage(content string) message.Message {
	return message.Message{
		Role:    message.RoleAssistant,
		Content: content,
	}
}

func buildToolResultMessage(toolUseID, content string, isError bool) message.Message {
	return message.Message{
		Role: message.RoleUser,
		ToolResult: &message.ToolResult{
			ToolUseID: toolUseID,
			Content:   content,
			IsError:   isError,
		},
	}
}

func (runner *Runner) buildModelMessages(history []message.Message) []message.Message {
	messages := make([]message.Message, 0, len(history)+1)
	messages = append(messages, buildSystemMessage(runner.buildSystemPrompt()))
	for _, msg := range history {
		rendered := renderMessageForModel(msg)
		// 跳过空 content 的 assistant 消息，避免发送 {"role":"assistant"} 触发 API 400 错误。
		// 空 assistant 消息可能来自模型返回空流式内容的边界情况。
		if rendered.Role == message.RoleAssistant && rendered.Content == "" {
			continue
		}
		messages = append(messages, rendered)
	}
	return messages
}

// 构建系统提示词
func (runner *Runner) buildSystemPrompt() string {
	descriptions := []string{}
	if runner.registry != nil {
		descriptions = runner.registry.Describe()
	}
	if runner.prompt == nil {
		runner.prompt = NewPromptBuilder(NewInstructionManager(""))
	}
	return runner.prompt.Build(descriptions)
}

func renderMessageForModel(msg message.Message) message.Message {
	switch {
	case msg.ToolUse != nil:
		return message.Message{
			Role:    message.RoleAssistant,
			Content: marshalJSON(toolUseEnvelope{Type: toolUseResponseType, ID: msg.ToolUse.ID, Name: msg.ToolUse.Name, Input: msg.ToolUse.Input}),
		}
	case msg.ToolResult != nil:
		return message.Message{
			Role:    message.RoleUser,
			Content: "TOOL_RESULT:\n" + marshalJSON(msg.ToolResult),
		}
	default:
		return message.Message{
			Role:    msg.Role,
			Content: msg.Content,
		}
	}
}

func marshalJSON(v any) string {
	data, err := json.Marshal(v)
	if err != nil {
		return ""
	}
	return string(data)
}

func (runner *Runner) consumeStream(ctx context.Context, events <-chan model.StreamEvent) (message.Message, error) {
	var state turnState

	for ev := range events {
		msg, done, err := runner.handleEvent(&state, ev)
		if err != nil {
			return message.Message{}, err
		}
		if done {
			return msg, nil
		}
	}

	return runner.finishWithoutDone(ctx, state)
}

func (runner *Runner) handleEvent(state *turnState, ev model.StreamEvent) (message.Message, bool, error) {
	if ev.Err != nil {
		return message.Message{}, false, runner.failAfterPartialOutput(state.wroteOutput, ev.Err)
	}
	if ev.Usage != nil {
		runner.mu.Lock()
		runner.usage = *ev.Usage
		runner.usageKnown = true
		runner.mu.Unlock()
	}

	if err := runner.appendDelta(state, ev.Delta); err != nil {
		return message.Message{}, false, err
	}

	if !ev.Done {
		return message.Message{}, false, nil
	}

	msg, err := runner.finalizeAssistantMessage(state)
	return msg, true, err
}

func (runner *Runner) clearTurnUsage() {
	runner.mu.Lock()
	runner.usage = model.Usage{}
	runner.usageKnown = false
	runner.mu.Unlock()
}

func (runner *Runner) appendDelta(state *turnState, delta string) error {
	if delta == "" {
		return nil
	}

	state.content.WriteString(delta)

	switch state.outputMode {
	case outputModeVisible:
		return runner.writeDelta(state, delta)
	case outputModeSuppressed:
		return nil
	}

	state.pending.WriteString(delta)
	state.outputMode = detectOutputMode(state.content.String())
	if state.outputMode == outputModeUndecided {
		return nil
	}
	if state.outputMode == outputModeSuppressed {
		state.pending.Reset()
		return nil
	}

	pending := state.pending.String()
	state.pending.Reset()
	return runner.writeDelta(state, pending)
}

func detectOutputMode(content string) outputMode {
	trimmed := strings.TrimSpace(content)
	if trimmed == "" {
		return outputModeUndecided
	}

	// 只要当前累计内容里已经能提取出合法 tool_use，就直接压制输出。
	if _, ok := extractToolUseEnvelope(trimmed); ok {
		return outputModeSuppressed
	}

	// 对“看起来像工具前置说明”的内容持续保持观望，避免模型先输出大段
	// “我将使用工具……”，随后再跟 fenced tool_use JSON。
	if looksLikeToolPreamble(trimmed) {
		return outputModeUndecided
	}

	// 模型有时会把 tool_use JSON 包在 Markdown fence 里返回。
	// 这里一旦看到 “{” 或 “`” 开头，就先抑制输出，等 finalize 再判定
	// 它到底是工具调用还是普通文本，避免把 tool_use JSON 泄漏到终端。
	if strings.HasPrefix(trimmed, "{") || strings.HasPrefix(trimmed, "`") {
		return outputModeSuppressed
	}

	return outputModeVisible
}

func looksLikeToolPreamble(trimmed string) bool {
	lower := strings.ToLower(trimmed)
	hints := []string{
		"我将",
		"我会",
		"我来",
		"好的，我来",
		"让我",
		"先使用",
		"首先使用",
		"读取",
		"读出",
		"遍历",
		"列出",
		"查看",
		"i will",
		"i'll",
		"let me",
		"tool_use",
		"<invoke",
		"工具",
		"调用",
		"使用",
		"ls",
		"read",
		"write",
		"grep",
		"glob",
		"bash",
		"webfetch",
		"```",
	}
	for _, hint := range hints {
		if strings.Contains(lower, strings.ToLower(hint)) {
			return true
		}
	}
	return false
}

func (runner *Runner) writeDelta(state *turnState, delta string) error {
	if delta == "" {
		return nil
	}

	if err := runner.ui.OnAssistantDelta(delta); err != nil {
		return runner.failAfterPartialOutput(state.wroteOutput, err)
	}
	state.wroteOutput = true
	return nil
}

func (runner *Runner) finalizeAssistantMessage(state *turnState) (message.Message, error) {
	msg := parseAssistantMessage(state.content.String())
	if msg.ToolUse != nil {
		return msg, nil
	}

	if !state.wroteOutput {
		if err := runner.writeDelta(state, msg.Content); err != nil {
			return message.Message{}, err
		}
	}
	if err := runner.ui.OnDone(); err != nil {
		return message.Message{}, err
	}

	return msg, nil
}

func parseAssistantMessage(content string) message.Message {
	trimmed := strings.TrimSpace(content)
	if trimmed == "" {
		return buildAssistantMessage("")
	}

	envelope, ok := extractToolUseEnvelope(trimmed)
	if !ok {
		return buildAssistantMessage(content)
	}
	if envelope.ID == "" {
		envelope.ID = envelope.Name
	}

	return message.Message{
		Role: message.RoleAssistant,
		ToolUse: &message.ToolCall{
			ID:    envelope.ID,
			Name:  envelope.Name,
			Input: envelope.Input,
		},
	}
}

// extractToolUseEnvelope 从 assistant 输出中提取第一个合法的 tool_use 对象。
// 当前兼容四类格式：
// 1) 整段内容就是裸 JSON
// 2) 整段内容就是 fenced JSON
// 3) 说明文字中嵌入 fenced JSON 或裸 JSON
// 4) Claude/DeepSeek 兼容的 <invoke> + DSML 参数块
func extractToolUseEnvelope(trimmed string) (toolUseEnvelope, bool) {
	if envelope, ok := decodeToolUseEnvelope(trimmed); ok {
		return envelope, true
	}

	if payload, ok := extractFencedToolUsePayload(trimmed); ok {
		return decodeToolUseEnvelope(payload)
	}

	if payload, ok := extractEmbeddedJSONObject(trimmed); ok {
		return decodeToolUseEnvelope(payload)
	}

	if envelope, ok := extractInvokeToolUseEnvelope(trimmed); ok {
		return envelope, true
	}

	return toolUseEnvelope{}, false
}

func decodeToolUseEnvelope(payload string) (toolUseEnvelope, bool) {
	payload = strings.TrimSpace(payload)
	if !strings.HasPrefix(payload, "{") {
		return toolUseEnvelope{}, false
	}

	var envelope toolUseEnvelope
	if err := json.Unmarshal([]byte(payload), &envelope); err != nil {
		return toolUseEnvelope{}, false
	}
	if envelope.Type != toolUseResponseType || envelope.Name == "" {
		return toolUseEnvelope{}, false
	}
	return envelope, true
}

func extractMarkdownFenceBody(trimmed string) (string, bool) {
	rest := strings.TrimPrefix(trimmed, "```")
	newlineIndex := strings.IndexByte(rest, '\n')
	if newlineIndex == -1 {
		return "", false
	}

	bodyWithClose := rest[newlineIndex+1:]
	closeIndex := strings.LastIndex(bodyWithClose, "```")
	if closeIndex == -1 {
		return "", false
	}

	return bodyWithClose[:closeIndex], true
}

// extractFencedToolUsePayload 在整段文本中搜索 fenced code block，
// 并返回第一个看起来像 tool_use JSON 的 body。
func extractFencedToolUsePayload(trimmed string) (string, bool) {
	searchFrom := 0
	for {
		start := strings.Index(trimmed[searchFrom:], "```")
		if start == -1 {
			return "", false
		}
		start += searchFrom

		body, next, ok := extractFenceBodyAt(trimmed, start)
		if !ok {
			return "", false
		}
		body = strings.TrimSpace(body)
		if _, ok := decodeToolUseEnvelope(body); ok {
			return body, true
		}
		searchFrom = next
	}
}

func extractFenceBodyAt(content string, start int) (body string, next int, ok bool) {
	rest := content[start:]
	if !strings.HasPrefix(rest, "```") {
		return "", len(content), false
	}

	rest = strings.TrimPrefix(rest, "```")
	newlineIndex := strings.IndexByte(rest, '\n')
	if newlineIndex == -1 {
		return "", len(content), false
	}

	bodyWithClose := rest[newlineIndex+1:]
	closeIndex := strings.Index(bodyWithClose, "```")
	if closeIndex == -1 {
		return "", len(content), false
	}

	consumed := start + 3 + newlineIndex + 1 + closeIndex + 3
	return bodyWithClose[:closeIndex], consumed, true
}

// extractEmbeddedJSONObject 在整段文本中搜索平衡的 JSON 对象，
// 并返回第一个可解析为 tool_use 的对象。
func extractEmbeddedJSONObject(trimmed string) (string, bool) {
	for start := strings.IndexByte(trimmed, '{'); start != -1; {
		payload, next, ok := extractBalancedJSONObject(trimmed, start)
		if ok {
			if _, matched := decodeToolUseEnvelope(payload); matched {
				return payload, true
			}
		}

		if next >= len(trimmed) {
			break
		}
		relative := strings.IndexByte(trimmed[next:], '{')
		if relative == -1 {
			break
		}
		start = next + relative
	}
	return "", false
}

func extractBalancedJSONObject(content string, start int) (string, int, bool) {
	if start < 0 || start >= len(content) || content[start] != '{' {
		return "", len(content), false
	}

	depth := 0
	inString := false
	escaped := false

	for i := start; i < len(content); i++ {
		ch := content[i]

		if inString {
			if escaped {
				escaped = false
				continue
			}
			if ch == '\\' {
				escaped = true
				continue
			}
			if ch == '"' {
				inString = false
			}
			continue
		}

		switch ch {
		case '"':
			inString = true
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				return content[start : i+1], i + 1, true
			}
		}
	}

	return "", len(content), false
}

func extractInvokeToolUseEnvelope(content string) (toolUseEnvelope, bool) {
	lower := strings.ToLower(content)
	start := strings.Index(lower, "<invoke")
	if start == -1 {
		return toolUseEnvelope{}, false
	}

	tagEnd := strings.Index(content[start:], ">")
	if tagEnd == -1 {
		return toolUseEnvelope{}, false
	}
	tagEnd += start

	openTag := content[start : tagEnd+1]
	name := extractTagAttribute(openTag, "name")
	if name == "" {
		return toolUseEnvelope{}, false
	}

	bodyStart := tagEnd + 1
	closeRel := strings.Index(strings.ToLower(content[bodyStart:]), "</invoke>")
	if closeRel == -1 {
		return toolUseEnvelope{}, false
	}

	input := decodeInvokeInput(content[bodyStart : bodyStart+closeRel])
	return toolUseEnvelope{
		Type:  toolUseResponseType,
		Name:  name,
		Input: input,
	}, true
}

func decodeInvokeInput(body string) json.RawMessage {
	body = strings.TrimSpace(body)
	if strings.HasPrefix(body, "{") && json.Valid([]byte(body)) {
		return json.RawMessage(body)
	}

	params := make(map[string]string)
	searchFrom := 0
	for searchFrom < len(body) {
		openRel := strings.Index(body[searchFrom:], "<")
		if openRel == -1 {
			break
		}
		open := searchFrom + openRel
		if open+1 < len(body) && body[open+1] == '/' {
			searchFrom = open + 2
			continue
		}

		tagEndRel := strings.Index(body[open:], ">")
		if tagEndRel == -1 {
			break
		}
		tagEnd := open + tagEndRel
		openTag := body[open : tagEnd+1]
		paramName := extractTagAttribute(openTag, "name")
		tagName := extractTagName(openTag)
		if paramName == "" || tagName == "" {
			searchFrom = tagEnd + 1
			continue
		}

		closeTag := "</" + tagName + ">"
		valueStart := tagEnd + 1
		closeRel := strings.Index(body[valueStart:], closeTag)
		if closeRel == -1 {
			searchFrom = tagEnd + 1
			continue
		}
		valueEnd := valueStart + closeRel
		params[paramName] = html.UnescapeString(strings.TrimSpace(body[valueStart:valueEnd]))
		searchFrom = valueEnd + len(closeTag)
	}

	if len(params) == 0 {
		return json.RawMessage(`{}`)
	}
	raw, err := json.Marshal(params)
	if err != nil {
		return json.RawMessage(`{}`)
	}
	return raw
}

func extractTagName(tag string) string {
	tag = strings.TrimSpace(strings.TrimPrefix(tag, "<"))
	tag = strings.TrimSuffix(tag, ">")
	tag = strings.TrimSpace(tag)
	if tag == "" || strings.HasPrefix(tag, "/") {
		return ""
	}
	for i, r := range tag {
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '/' {
			return tag[:i]
		}
	}
	return tag
}

func extractTagAttribute(tag, name string) string {
	for _, quote := range []byte{'"', '\''} {
		prefix := name + "=" + string(quote)
		start := strings.Index(tag, prefix)
		if start == -1 {
			continue
		}
		valueStart := start + len(prefix)
		valueEndRel := strings.IndexByte(tag[valueStart:], quote)
		if valueEndRel == -1 {
			return ""
		}
		return html.UnescapeString(tag[valueStart : valueStart+valueEndRel])
	}
	return ""
}

func (runner *Runner) finishWithoutDone(ctx context.Context, state turnState) (message.Message, error) {
	if state.wroteOutput {
		_ = runner.ui.OnDone()
	}
	if ctx.Err() != nil {
		return message.Message{}, ctx.Err()
	}

	return message.Message{}, fmt.Errorf("模型流在未发送完成事件时结束")
}

func (runner *Runner) failAfterPartialOutput(wroteOutput bool, err error) error {
	if wroteOutput {
		_ = runner.ui.OnDone()
	}
	return err
}

func (runner *Runner) runToolCall(ctx context.Context, call *message.ToolCall) (message.Message, error) {
	if call == nil {
		return buildToolResultMessage("", "tool call is nil", true), nil
	}

	if err := runner.ui.OnToolCall(ui.ToolCallEvent{
		ID:    call.ID,
		Name:  call.Name,
		Input: append(json.RawMessage(nil), call.Input...),
	}); err != nil {
		return message.Message{}, err
	}

	result := runner.executeToolCall(ctx, call)
	if err := runner.ui.OnToolResult(ui.ToolResultEvent{
		ToolUseID: result.ToolResult.ToolUseID,
		Name:      call.Name,
		Content:   result.ToolResult.Content,
		IsError:   result.ToolResult.IsError,
	}); err != nil {
		return message.Message{}, err
	}

	return result, nil
}

func (runner *Runner) executeToolCall(ctx context.Context, call *message.ToolCall) message.Message {
	if runner.registry == nil {
		return buildToolResultMessage(call.ID, "tool registry is nil", true)
	}

	selectedTool, ok := runner.registry.Get(call.Name)
	if !ok {
		return buildToolResultMessage(call.ID, fmt.Sprintf("unknown tool: %s", call.Name), true)
	}

	output, err := selectedTool.Run(ctx, call.Input)
	if err != nil {
		return buildToolResultMessage(call.ID, err.Error(), true)
	}

	return buildToolResultMessage(call.ID, output, false)
}

func estimateMessagesTokens(messages []message.Message) int {
	total := 0
	for _, msg := range messages {
		total += estimateTextTokens(string(msg.Role))
		total += estimateTextTokens(msg.Content)
		if msg.ToolUse != nil {
			total += estimateTextTokens(msg.ToolUse.ID)
			total += estimateTextTokens(msg.ToolUse.Name)
			total += estimateTextTokens(string(msg.ToolUse.Input))
		}
		if msg.ToolResult != nil {
			total += estimateTextTokens(msg.ToolResult.ToolUseID)
			total += estimateTextTokens(msg.ToolResult.Content)
		}
		total += 4
	}
	return total
}

func estimateTextTokens(text string) int {
	runes := len([]rune(text))
	if runes == 0 {
		return 0
	}
	return (runes + 3) / 4
}

package bubble

import (
	"fmt"
	"gocode/internal/loop"
	"gocode/internal/settings"
	"math"
	"strings"
)

const contextMeterCells = 40

func (m appModel) contextMeterTitle() string {
	stats := m.contextStats()
	limit := maxInt(1, stats.LimitTokens)
	used := clampInt(stats.UsedTokens, 0, limit)
	cache := clampInt(stats.CacheTokens, 0, used)
	usedPercent := percent(used, limit)
	cachePercent := percent(cache, limit)
	freePercent := maxInt(0, 100-int(math.Round(usedPercent)))
	return fmt.Sprintf("%d%%(%.1f%%) %s %d%%", int(math.Round(usedPercent)), cachePercent, renderContextBar(used, cache, limit), freePercent)
}

func (m appModel) contextStats() loop.ContextStats {
	cfg := m.currentSettings()
	limit := cfg.UI.ContextLimitTokens
	if provider, ok := m.runner.(contextStatsProvider); ok {
		return provider.ContextStats(limit, m.input.Value())
	}
	return loop.ContextStats{LimitTokens: limit}
}

func (m appModel) currentSettings() settings.Config {
	if m.settingsConfig == nil {
		return settings.DefaultConfig()
	}
	return settings.Normalize(m.settingsConfig.CurrentSettings())
}

func renderContextBar(used, cache, limit int) string {
	limit = maxInt(1, limit)
	usedCells := int(math.Round(float64(clampInt(used, 0, limit)) / float64(limit) * contextMeterCells))
	cacheCells := int(math.Round(float64(clampInt(cache, 0, used)) / float64(limit) * contextMeterCells))
	if cacheCells > usedCells {
		cacheCells = usedCells
	}
	var out strings.Builder
	for i := 0; i < contextMeterCells; i++ {
		switch {
		case i < cacheCells:
			out.WriteString(contextCacheStyle.Render("▰"))
		case i < usedCells:
			out.WriteString(contextUsedStyle.Render("▰"))
		default:
			out.WriteString(contextFreeStyle.Render("▱"))
		}
	}
	return out.String()
}

func percent(value, total int) float64 {
	if total <= 0 {
		return 0
	}
	return float64(value) / float64(total) * 100
}

func clampInt(value, minValue, maxValue int) int {
	if value < minValue {
		return minValue
	}
	if value > maxValue {
		return maxValue
	}
	return value
}

// 本文件定义 TUI 颜色管理器，集中维护主题色和光标颜色。
package bubble

